'use strict';
// Approved phone Tacho cards, populated exclusively by the current driver's
// response. Unknown facts stay in their original cards without DEMO values.
((root,factory)=>{const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.SuperSpedytorDesignedTacho=api;})(typeof window==='undefined'?null:window,()=>{
  const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon=name=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
  const known=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v))&&Number(v)>=0;
  const duration=v=>known(v)?`${Math.floor(Number(v)/3600)}:${String(Math.floor(Number(v)%3600/60)).padStart(2,'0')}`:'—';
  const clock=v=>v&&!Number.isNaN(new Date(v).getTime())?new Date(v).toLocaleString('pl-PL',{timeZone:'Europe/Warsaw',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';
  function render(data,view){
    const ready=view.ready&&!view.stale,c=ready?data.compliance:{},rest=ready?view.rest:null;
    const daily=c.daily||{},weekly=c.weekly||{},coverage=c.coverage||{};
    const heading=(title,caption)=>`<div class="tacho-section-heading"><h3>${e(title)}</h3><span>${e(caption)}</span></div>`;
    const metric=(label,value,limit,cls='',note='')=>`<article class="tacho-metric ${cls}"><small>${e(label)}</small><strong>${duration(value)}</strong><p>${e(known(value)?note||'Według odczytu TMS':'Brak danych')}</p>${known(value)&&known(limit)&&Number(limit)>0?`<div class="tacho-mini-progress" aria-hidden="true"><span style="--progress:${Math.min(100,Number(value)/Number(limit)*100)}%"></span></div>`:''}</article>`;
    const restCard=rest?`<section class="tacho-active-card"><span class="tacho-active-badge"><span></span>Teraz · odpoczynek</span><h3>${e(rest.title)}</h3><p>Odpoczynek od ${e(rest.startText||'nieustalonej godziny')}</p><span class="tacho-counter-label">Upłynęło odpoczynku</span><strong class="tacho-elapsed" data-rest-elapsed>${e(rest.elapsedText)}</strong><div class="tacho-progress"><span style="--progress:${rest.progress*100}%"></span></div><div class="tacho-progress-labels"><span>Do końca wybranego odpoczynku</span><b data-rest-remaining>${e(rest.remainingText)}</b></div><p>${rest.baseS?`Podstawa: ${duration(rest.baseS)}${rest.compensationS!==null?' + rekompensata '+duration(rest.compensationS):' · brak danych o rekompensacie'}`:'Wybierz wymiar trwającej przerwy lub odpoczynku.'}</p><p class="tacho-end-time">${rest.endText?`${rest.estimated?'Szacowany koniec':'Koniec wybranego odpoczynku'}: <strong>${e(rest.endText)}</strong>`:rest.minimumEndMs?`Koniec minimum bez rekompensaty: ${clock(rest.minimumEndMs)}. Pełny termin wymaga danych o rekompensacie.`:'Brak danych do obliczenia końca odpoczynku.'}</p>${rest.estimated?'<p>Obliczenie na podstawie dostępnego odczytu i historii. Niepełna historia może zmienić termin.</p>':''}<div class="tacho-active-actions"><button class="tacho-change-button" data-live-open-rest>${rest.type?'Zmień rodzaj':'Wybierz odpoczynek'}</button></div></section>`:'';
    const now=restCard||`<section class="tacho-now-card"><div class="tacho-now-top"><span class="tacho-status"><span class="tacho-status-dot"></span>${e(ready?view.mode.label:'Stan odczytu')}</span></div><div class="tacho-driver-instruction"><span>${ready?e(view.hero?.label||'Bieżąca aktywność'):'Aktualny odczyt niedostępny'}</span><strong class="tacho-primary-time">${e(ready?view.hero?.text||'—':'—')}</strong><p>${e(ready?view.breakPlan?.text||'Czasy pochodzą z Twojego odczytu TMS.':view.stale?'Dane są nieaktualne. Odśwież odczyt.':'TMS nie zwrócił stanu tachografu.')}</p></div><button class="tacho-report-button" data-live-open-rest>${icon('clock')}Zgłaszam przerwę lub odpoczynek</button><div class="tacho-driver-fact"><span>Jazda od pełnej przerwy</span><strong>${duration(c.break?.continuous_drive_s)}</strong></div></section>`;
    const restRow=(label,value,note,kind)=>`<div class="tacho-rest-row"><span class="tacho-rest-icon">${icon(kind)}</span><div><small>${e(label)}</small><strong>${e(value)}</strong></div><b>${e(note)}</b></div>`;
    const reductions=coverage.daily_complete===true&&known(weekly.reduced_rests)?Number(weekly.reduced_rests):null;
    const tens=coverage.weekly_complete===true&&known(weekly.tens_used)?Number(weekly.tens_used):null;
    const lastRest=weekly.last_regular_rest_end||weekly.last_reduced_rest_end;
    const current=ready?`<div class="tacho-period current"><time>${clock(c.current?.since)}</time><span class="tacho-activity-icon ${e(view.mode.key)}">${icon(view.mode.key==='rest'?'parking':view.mode.key==='drive'?'truck':'clock')}</span><span><strong>${e(view.mode.label)}</strong><small>${rest?e(rest.elapsedText)+' · upłynęło':duration(c.current?.duration_s)+' · wg odczytu'}</small></span></div>`:'<p>Brak danych o bieżącej aktywności.</p>';
    return `<div class="tacho-screen lw-tacho-designed"><header class="tacho-heading"><span class="tacho-kicker">${icon('clock')}Panel kierowcy · dane TMS</span><h2>Czas pod kontrolą</h2><p>${e(view.lastDataAgoText?'Odczyt: '+view.lastDataAgoText+' temu':'Brak daty odczytu')}</p></header>${now}
      ${heading('Ramy dnia','Pełny odpoczynek 11 godzin')}<section class="tacho-day-window"><div><small>Dzień rozpoczęty</small><strong>${clock(daily.shift_start)}</strong><span>${daily.shift_start?'po odpoczynku dobowym':'Brak danych'}</span></div><span class="tacho-day-arrow">${icon('arrow')}</span><div class="deadline"><small>Zakończ najpóźniej</small><strong>${clock(daily.rest_due_at)}</strong><span>${daily.rest_due_at?'według odczytu TMS':'Brak danych'}</span></div></section>
      ${heading('Jazda i „dziewiątki”','Twój bilans jazdy i odpoczynków')}<div class="tacho-metrics">${metric('Dzisiaj · limit '+duration(daily.limit_s),daily.drive_s,daily.limit_s,'tacho-drive-metric',known(daily.remaining_s)?'zostało '+duration(daily.remaining_s)+' jazdy':'Brak dostępnego czasu jazdy')}
      <article class="tacho-metric tacho-nine-metric"><small>Skrócone odpoczynki 9 h</small><strong>${reductions===null?'—':reductions+' z 3'}</strong><p>${reductions===null?'Brak pełnej historii':'zostało '+Math.max(0,3-reductions)+' do odpoczynku tygodniowego'}</p></article>
      <article class="tacho-extension-card"><span class="tacho-extension-mark">10 h</span><span class="tacho-extension-copy"><small>Przedłużenia jazdy do 10 h</small><strong>${tens===null?'—':tens+' z 2 wykorzystane'}</strong></span><b>${tens===null?'Brak pełnej historii':'Zostało '+Math.max(0,2-tens)}</b></article>
      ${metric('Ten tydzień',weekly.drive_s,201600,'tacho-week-metric',known(weekly.remaining_s)?'zostało '+duration(weekly.remaining_s):'Brak pozostałego czasu')}${metric('Dwa kolejne tygodnie',weekly.fortnight_drive_s,324000,'tacho-fortnight-metric',known(weekly.fortnight_remaining_s)?'zostało '+duration(weekly.fortnight_remaining_s):'Brak pozostałego czasu')}</div>
      ${heading('Dzisiejsza aktywność','Bieżący okres z TMS')}<section class="tacho-activity-card"><div class="tacho-period-list">${current}</div><p>Pełna lista okresów dzisiejszej aktywności nie jest dostępna w tym odczycie.</p></section>
      ${heading('Odpoczynki','Najważniejsze terminy')}<section class="tacho-rest-list">${restRow('Ostatni odpoczynek tygodniowy',lastRest?clock(lastRest):'—',lastRest?'zakończony':'Brak danych','check')}${restRow('Następny odpoczynek dobowy',daily.rest_due_at?clock(daily.rest_due_at):'—',daily.rest_due_at?'termin według TMS':'Brak danych','clock')}</section>
      <div class="tacho-source-note">${icon('info')}<p><strong>Tachograf jest źródłem nadrzędnym.</strong> Licznik biegnie na telefonie od odczytanej godziny rozpoczęcia. Koniec wybranego odpoczynku nie potwierdza pozostałych limitów jazdy i pracy.</p></div></div>`;
  }
  return {render};
});
